package dev.industrialtechnology.client;
import net.minecraft.client.renderer.tileentity.TileEntitySpecialRenderer;import net.minecraft.tileentity.TileEntity;import org.lwjgl.opengl.GL11;import java.util.*;import dev.industrialtechnology.railway.*;
/** Track geometry is shared by shape and orientation; no meshes rebuilt while trains move. */
public final class TrackRenderer extends TileEntitySpecialRenderer {
 private static final Map<Integer,Integer> cache=new HashMap<>();public static void clear(){for(int id:cache.values())GL11.glDeleteLists(id,1);cache.clear();}@Override public void renderTileEntityAt(TileEntity raw,double x,double y,double z,float p){TileTrack t=(TileTrack)raw;int key=t.shape+t.facing*8;Integer id=cache.get(key);if(id==null){id=GL11.glGenLists(1);GL11.glNewList(id,GL11.GL_COMPILE);for(int b=0;b<(t.shape==4?2:1);b++){RailPath path=new RailPath(.5,.125,.5,t.facing,t.shape,b);for(double s=0;s<path.length;s+=.5){double[] a=path.point(s),c=path.point(Math.min(path.length,s+.52));double yaw=path.yaw(s);GL11.glPushMatrix();GL11.glTranslated(a[0],a[1]-.125,a[2]);GL11.glRotated(-yaw,0,1,0);RailMesh.box(0,0,0,2.5,.12,.21,8);for(double xx:new double[]{-.7175,.7175}){RailMesh.box(xx,.12,.25,.065,.12,.55,2);RailMesh.box(xx,.11,.25,.14,.025,.55,0);}GL11.glPopMatrix();}}GL11.glEndList();cache.put(key,id);}GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glPushMatrix();try{bindTexture(RailMesh.MATERIALS);GL11.glColor4f(1,1,1,1);GL11.glDisable(GL11.GL_CULL_FACE);GL11.glTranslated(x,y,z);GL11.glCallList(id);if(t.shape==4){RailMesh.box(.5,.2,.5,.25,.2,.25,t.switched?4:9);}if(t.station){RailMesh.box(.5,.2,.5,.3,.15,.3,7);}}finally{GL11.glPopMatrix();GL11.glPopAttrib();}}
}
